using System.Windows; using System.Windows.Controls; using System.Windows.Input; namespace zpX.UI.Controls{ public partial class TitleBar:UserControl{ public TitleBar(){ InitializeComponent(); MinBtn.Click+=(s,e)=>{var w=Window.GetWindow(this); if(w!=null) w.WindowState=WindowState.Minimized;}; MaxBtn.Click+=(s,e)=>{var w=Window.GetWindow(this); if(w!=null){ w.WindowState = w.WindowState==WindowState.Maximized?WindowState.Normal:WindowState.Maximized;}}; CloseBtn.Click+=(s,e)=>{var w=Window.GetWindow(this); if(w!=null) w.Close();}; this.MouseLeftButtonDown+=(s,e)=>{var w=Window.GetWindow(this); if(w!=null && e.ButtonState==MouseButtonState.Pressed){ try{w.DragMove();}catch{}}};}}}